-- Prospect AI initial schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.leads(
 id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,
 company_name text not null check(char_length(company_name) between 1 and 200),website text not null default '' check(char_length(website)<=500),industry text not null default '' check(char_length(industry)<=120),location text not null default '' check(char_length(location)<=180),contact_name text not null default '' check(char_length(contact_name)<=160),contact_email text not null default '' check(char_length(contact_email)<=254),notes text not null default '' check(char_length(notes)<=4000),
 status text not null default 'new' check(status in ('new','qualified','contacted','replied','won','lost','archived')),score integer not null default 0 check(score between 0 and 100),score_reasons jsonb not null default '[]'::jsonb,source text not null default 'manual' check(char_length(source)<=100),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint leads_id_user_unique unique(id,user_id));
create table if not exists public.outreach_drafts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null,subject text not null check(char_length(subject) between 1 and 300),body text not null check(char_length(body) between 1 and 10000),status text not null default 'draft' check(status in ('draft','approved','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint drafts_lead_owner_fk foreign key(lead_id,user_id) references public.leads(id,user_id) on delete cascade);
create index if not exists leads_user_created_idx on public.leads(user_id,created_at desc); create index if not exists leads_user_status_idx on public.leads(user_id,status); create index if not exists drafts_user_created_idx on public.outreach_drafts(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.leads enable row level security; alter table public.outreach_drafts enable row level security;
drop policy if exists "Users read own profile" on public.profiles; create policy "Users read own profile" on public.profiles for select using(auth.uid()=id);
drop policy if exists "Users insert own profile" on public.profiles; create policy "Users insert own profile" on public.profiles for insert with check(auth.uid()=id);
drop policy if exists "Users update own profile" on public.profiles; create policy "Users update own profile" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "Users manage own leads" on public.leads; create policy "Users manage own leads" on public.leads for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "Users manage own drafts" on public.outreach_drafts; create policy "Users manage own drafts" on public.outreach_drafts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists profiles_updated_at on public.profiles; create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
drop trigger if exists leads_updated_at on public.leads; create trigger leads_updated_at before update on public.leads for each row execute function public.set_updated_at();
drop trigger if exists drafts_updated_at on public.outreach_drafts; create trigger drafts_updated_at before update on public.outreach_drafts for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
